func expandPageQuadParams(dst *[]any, dialect runtime.Dialect, p PageQuadParams) error {
	_ = dialect
	_ = p
	if p.Seek.IsActive() {
		if len(p.Seek.Values) != 4 {
			return runtime.ErrInvalidSeek
		}
		runtime.AppendSeekArgs(dst, dialect, p.Order, 4, p.Seek.Values)
	}
	if !runtime.OrderValid(p.Order) {
		return runtime.ErrInvalidOrder
	}
	*dst = append(*dst, p.Limit)
	return nil
}

func expandPageQuadArgs(dst *[]any, dialect runtime.Dialect, q *runtime.Query) error {
	return expandPageQuadParams(dst, dialect, q.Params.(PageQuadParams))
}

func computePageQuadKey(p PageQuadParams) (runtime.VariantKey, uint64, uint64, int) {
	_ = p
	var colMask uint64
	colMask = p.SelectCols & PageQuadColsAll
	if colMask == PageQuadColsAll {
		colMask = 0
	}
	var flagMask uint64
	var orderSpec runtime.Order
	var hasSeek bool
	hasSeek = p.Seek.IsActive()
	orderSpec = p.Order
	orderKey := runtime.EncodeOrderKey(orderSpec, hasSeek)
	approxArgs := 7
	vk := runtime.MakeVariantKey(stmtIDPageQuad, colMask, flagMask, orderKey)
	return vk, colMask, flagMask, approxArgs
}

// PageQuadQuery constructs a composable runtime.Query without executing it.
func PageQuadQuery(p PageQuadParams) runtime.Query {
	_, colMask, flagMask, _ := computePageQuadKey(p)
	in := runtime.RenderInput{
		ColMask:   colMask,
		FlagMask:  flagMask,
		OrderSpec: p.Order,
		HasSeek:   p.Seek.IsActive(),
	}
	orderKey := runtime.EncodeOrderKey(in.OrderSpec, in.HasSeek)
	shapeTag := runtime.ComputeSubqueryShape(stmtIDPageQuad, colMask, flagMask, orderKey, false)
	return runtime.Query{
		StmtID:   stmtIDPageQuad,
		Desc:     descPageQuad,
		Input:    in,
		Params:   p,
		Expand:   expandPageQuadArgs,
		ShapeTag: shapeTag,
	}
}

// PageQuadQuery constructs a composable runtime.Query without executing it.
func (q *Queries) PageQuadQuery(p PageQuadParams) runtime.Query {
	return PageQuadQuery(p)
}

func scanPageQuadRow(scanner interface{ Scan(...any) error }, dst *QuadItem, colMask uint64, p PageQuadParams) error {
	_ = colMask
	_ = p
	var item QuadItem
	var scanBuf [4]any
	scanCount := 0
	effMask := colMask
	if effMask == 0 {
		effMask = PageQuadColsAll
	}
	if (effMask & (1 << 0)) != 0 {
		scanBuf[scanCount] = &item.ID
		scanCount++
	}
	if (effMask & (1 << 1)) != 0 {
		scanBuf[scanCount] = &item.GroupKey
		scanCount++
	}
	if (effMask & (1 << 2)) != 0 {
		scanBuf[scanCount] = &item.Priority
		scanCount++
	}
	if (effMask & (1 << 3)) != 0 {
		scanBuf[scanCount] = &item.CreatedTs
		scanCount++
	}
	scanSlice := scanBuf[:scanCount]
	if err := scanner.Scan(scanSlice...); err != nil {
		return err
	}
	*dst = item
	return nil
}

func (q *Queries) PageQuad(ctx context.Context, p PageQuadParams) ([]QuadItem, error) {
	return runtime.Collect(q.PageQuadSeq(ctx, p))
}

func (q *Queries) PageQuadSeq(ctx context.Context, p PageQuadParams) iter.Seq2[QuadItem, error] {
	return func(yield func(QuadItem, error) bool) {
		var zero QuadItem
		vk, colMask, flagMask, approxArgs := computePageQuadKey(p)
		_ = colMask
		argBuf := runtime.AcquireArgsCap(approxArgs)
		defer runtime.ReleaseArgs(argBuf)
		if err := expandPageQuadParams(argBuf, sqlDialect, p); err != nil {
			yield(zero, err)
			return
		}
		in := runtime.RenderInput{
			ColMask:   colMask,
			FlagMask:  flagMask,
			OrderSpec: p.Order,
			HasSeek:   p.Seek.IsActive(),
		}
		sqlRows, ms, err := q.cache.Query(ctx, q.db, q.txCache, q.usePrepared, vk, stmtIDPageQuad, runtime.ComputeBatchShapeTag(colMask, flagMask), 0, nil, sqlDialect, descPageQuad, &in, (*argBuf)...)
		if err != nil {
			yield(zero, err)
			return
		}
		defer runtime.ReleaseRows(&sqlRows, &ms)
		var item QuadItem
		for sqlRows.Next() {
			if err := scanPageQuadRow(sqlRows, &item, colMask, p); err != nil {
				runtime.ReleaseRows(&sqlRows, &ms)
				yield(zero, err)
				return
			}
			if !yield(item, nil) {
				return
			}
		}
		err = sqlRows.Err()
		runtime.ReleaseRows(&sqlRows, &ms)
		if err != nil {
			yield(zero, err)
		}
	}
}

func (pl *Pipeline) PageQuad(p PageQuadParams) *runtime.SliceFuture[QuadItem] {
	vk, colMask, flagMask, approxArgs := computePageQuadKey(p)
	argBuf := runtime.AcquireArgsCap(approxArgs)
	expandErr := expandPageQuadParams(argBuf, sqlDialect, p)
	in := runtime.RenderInput{
		ColMask:   colMask,
		FlagMask:  flagMask,
		OrderSpec: p.Order,
		HasSeek:   p.Seek.IsActive(),
	}
	return runtime.QueueSlice(pl.Pipeline, stmtIDPageQuad, descPageQuad, in, vk, nil, argBuf, expandErr,
		func(rs *sql.Rows, dst *QuadItem) error { return scanPageQuadRow(rs, dst, colMask, p) },
	)
}
